void updatePlayingTrackVisibility() {
  final ctrlr = browserController;
  if (ctrlr == null) return;

  final path = playingPathRef.value;
  if (path == null || path.isEmpty || searchTerm.value.isNotEmpty) {
    // When searching we don't render per-track rows, so hide the action.
    ctrlr.playingTrackOutsideVisibleRegion.value = false;
    return;
  }

  final listContext = listKey.currentContext;
  final rowContext = rowKeys[path]?.currentContext;

  if (listContext == null || rowContext == null) {
    // If we haven't built the row, it's effectively offscreen.
    ctrlr.playingTrackOutsideVisibleRegion.value = true;
    return;
  }

  final listBox = listContext.findRenderObject();
  final rowBox = rowContext.findRenderObject();
  if (listBox is! RenderBox || rowBox is! RenderBox) {
    ctrlr.playingTrackOutsideVisibleRegion.value = true;
    return;
  }
  if (!listBox.hasSize || !rowBox.hasSize) {
    ctrlr.playingTrackOutsideVisibleRegion.value = true;
    return;
  }

  final listRect = listBox.localToGlobal(Offset.zero) & listBox.size;
  final rowRect = rowBox.localToGlobal(Offset.zero) & rowBox.size;
  final overlaps = rowRect.overlaps(listRect);
  ctrlr.playingTrackOutsideVisibleRegion.value = !overlaps;
}

// Keep visibility status current while mounted and as the user scrolls.
useEffect(() {
  if (browserController == null) return null;
  void listener() => updatePlayingTrackVisibility();
  scroll.addListener(listener);
  WidgetsBinding.instance.addPostFrameCallback((_) =>
      updatePlayingTrackVisibility());
  return () => scroll.removeListener(listener);
}, [scroll]);

useEffect(() {
  // Re-evaluate when a new track starts playing or when the search UI
  // swaps in/out.
  WidgetsBinding.instance.addPostFrameCallback((_) =>
      updatePlayingTrackVisibility());
  return null;
}, [playingPath, searchTerm.value]);

